/* generated by convert.py - NES master palette -> nearest TI VDP color */
#ifndef GEN_PALETTE_H
#define GEN_PALETTE_H
/* index by NES color (0..63), yields TI COLOR_* value (1..15) */
extern const unsigned char nes_to_ti[64];
/* ti_near[c] = the other 14 TI colours, nearest (RGB) to c first;
 * used to move room colours off colours the sprites use */
extern const unsigned char ti_near[16][14];
#endif
